node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

db.transaction(() => {
  // 1. Update order status, shipping status, and cancel reason
  const orderUpdate = db.prepare(\`
    UPDATE orders 
    SET status = 'cancelled', 
        shipping_status = 'cancelled', 
        cancel_reason = 'Customer requested cancellation'
    WHERE order_id = 'ORD-E0E671'
  \`);
  const orderResult = orderUpdate.run();
  console.log('Order updated:', orderResult.changes, 'row(s)');

  // 2. Update all order items to cancelled
  const itemsUpdate = db.prepare(\`
    UPDATE order_items 
    SET item_status = 'cancelled'
    WHERE order_id = 'ORD-E0E671'
  \`);
  const itemsResult = itemsUpdate.run();
  console.log('Items updated:', itemsResult.changes, 'row(s)');

  // 3. Record refund payment
  const refundInsert = db.prepare(\`
    INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id, created_at)
    VALUES ('ORD-E0E671', 'refund', 120.00, 'cc_21e6eed2', datetime('now'))
  \`);
  const refundResult = refundInsert.run();
  console.log('Refund payment recorded, id:', refundResult.lastInsertRowid);
})();

// Verify the changes
console.log('\n=== VERIFICATION ===');
const order = db.prepare(\"SELECT order_id, status, shipping_status, cancel_reason, total_paid FROM orders WHERE order_id = 'ORD-E0E671'\").get();
console.log('Order:', JSON.stringify(order, null, 2));

const items = db.prepare(\"SELECT oi_id, name, item_status FROM order_items WHERE order_id = 'ORD-E0E671'\").all();
console.log('Items:', JSON.stringify(items, null, 2));

const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-E0E671'\").all();
console.log('Payments:', JSON.stringify(payments, null, 2));

db.close();
"

